const message = $input.item.json.body.message || '';
const user_id = $input.item.json.body.user_id || 1;
const messageLower = message.toLowerCase();

let intent = 'faq';

// Giá thị trường
if (messageLower.includes('giá') || messageLower.includes('price') || messageLower.includes('bao nhiêu')) {
  intent = 'market_price';
}
// Công việc
else if (messageLower.includes('hôm nay') || messageLower.includes('công việc') || messageLower.includes('làm gì') || messageLower.includes('task')) {
  intent = 'daily_tasks';
}
// Khuyến nghị
else if (messageLower.includes('trồng') || messageLower.includes('khuyến nghị') || messageLower.includes('nên') || messageLower.includes('gợi ý')) {
  intent = 'recommendations';
}
// Vụ mùa
else if (messageLower.includes('vụ mùa') || messageLower.includes('mùa vụ') || messageLower.includes('season') || messageLower.includes('tiến độ') || messageLower.includes('thu hoạch')) {
  intent = 'seasons';
}
// Cảnh báo
else if (messageLower.includes('cảnh báo') || messageLower.includes('alert') || messageLower.includes('thời tiết') || messageLower.includes('sâu bệnh') || messageLower.includes('nguy hiểm')) {
  intent = 'alerts';
}
// Trang trại
else if (messageLower.includes('trang trại') || messageLower.includes('farm') || messageLower.includes('đất') || messageLower.includes('diện tích')) {
  intent = 'farms';
}
// Trợ giúp
else if (messageLower.includes('help') || messageLower.includes('trợ giúp') || messageLower.includes('hướng dẫn') || messageLower.includes('làm sao')) {
  intent = 'help';
}

return { json: { message, intent, user_id } };

const data = $input.all();
if (!data || data.length === 0 || !data[0].json.crop_name) {
  return { json: { answer: "📊 Hiện tại chưa có dữ liệu giá thị trường." } };
}
let response = "📊 **Giá thị trường hôm nay:**\n\n";
data.forEach((item, i) => {
  const d = item.json;
  if (d.crop_name) {
    const price = d.price_avg ? Math.round(d.price_avg).toLocaleString('vi-VN') : 'N/A';
    response += `${i+1}. **${d.crop_name}**: ${price} đ/kg\n   📍 ${d.market_location || 'Không xác định'}\n\n`;
  }
});
return { json: { answer: response } };

const data = $input.all();
if (!data || data.length === 0 || !data[0].json.task_name) {
  return { json: { answer: "✅ Tuyệt vời! Hiện tại bạn không có công việc nào cần làm." } };
}
let response = "✅ **Công việc cần làm:**\n\n";
data.forEach((item, i) => {
  const d = item.json;
  if (d.task_name) {
    response += `${i+1}. **${d.task_name}**\n`;
    if (d.description) response += `   📝 ${d.description}\n`;
    response += `   🌱 Cây: ${d.crop_name || 'Không xác định'}\n`;
    if (d.due_date) response += `   📅 Hạn: ${d.due_date}\n`;
    response += `\n`;
  }
});
return { json: { answer: response } };

const data = $input.all();
if (!data || data.length === 0 || !data[0].json.crop_name) {
  return { json: { answer: "🌾 Hiện tại chưa có khuyến nghị trồng trọt nào." } };
}
let response = "🌾 **Khuyến nghị trồng trọt:**\n\n";
data.forEach((item, i) => {
  const d = item.json;
  if (d.crop_name) {
    const price = d.expected_price ? Math.round(d.expected_price).toLocaleString('vi-VN') : 'N/A';
    const stars = '⭐'.repeat(Math.min(5 - (d.priority_level || 3) + 1, 5));
    response += `${i+1}. **${d.crop_name}** ${stars}\n`;
    response += `   💰 Giá dự kiến: ${price} đ/kg\n`;
    response += `   📌 ${d.reason || 'Phù hợp với điều kiện địa phương'}\n`;
    if (d.recommended_start_date) response += `   🗓️ Bắt đầu: ${d.recommended_start_date}\n`;
    response += `\n`;
  }
});
return { json: { answer: response } };

const data = $input.all();
if (!data || data.length === 0 || !data[0].json.season_code) {
  return { json: { answer: "🌱 Bạn chưa có vụ mùa nào đang hoạt động." } };
}
const statusMap = {'planning': '📋 Lên kế hoạch', 'active': '🌿 Đang canh tác', 'harvesting': '🌾 Đang thu hoạch', 'completed': '✅ Hoàn thành', 'cancelled': '❌ Đã hủy'};
let response = "🌱 **Tình trạng vụ mùa của bạn:**\n\n";
data.forEach((item, i) => {
  const d = item.json;
  const status = statusMap[d.status] || d.status;
  response += `${i+1}. **${d.crop_name}** - ${d.farm_name}\n`;
  response += `   📊 Trạng thái: ${status}\n`;
  response += `   📅 Bắt đầu: ${d.start_date || 'Chưa xác định'}\n`;
  response += `   🎯 Dự kiến thu hoạch: ${d.expected_harvest_date || 'Chưa xác định'}\n`;
  if (d.area_planted) response += `   📐 Diện tích: ${d.area_planted} ha\n`;
  if (d.expected_yield) response += `   📦 Sản lượng dự kiến: ${d.expected_yield} tấn\n`;
  response += `\n`;
});
return { json: { answer: response } };

const data = $input.all();
if (!data || data.length === 0 || !data[0].json.title) {
  return { json: { answer: "✅ Hiện tại không có cảnh báo nào cho khu vực của bạn." } };
}
const severityIcon = {'high': '🔴', 'medium': '🟡', 'low': '🟢'};
let response = "⚠️ **Cảnh báo hiện tại:**\n\n";
data.forEach((item, i) => {
  const d = item.json;
  const icon = severityIcon[d.severity] || '⚪';
  response += `${icon} **${d.title}**\n`;
  response += `   📋 ${d.message}\n`;
  response += `   🏷️ Loại: ${d.alert_type}\n`;
  if (d.valid_until) response += `   ⏰ Hiệu lực đến: ${d.valid_until}\n`;
  response += `\n`;
});
return { json: { answer: response } };

const data = $input.all();
if (!data || data.length === 0 || !data[0].json.name) {
  return { json: { answer: "🏡 Bạn chưa đăng ký trang trại nào." } };
}
let response = "🏡 **Thông tin trang trại của bạn:**\n\n";
data.forEach((item, i) => {
  const d = item.json;
  response += `${i+1}. **${d.name}**\n`;
  response += `   📐 Diện tích: ${d.area_hectare || 'N/A'} ha\n`;
  response += `   🌍 Loại đất: ${d.soil_type || 'Chưa xác định'}\n`;
  response += `   💧 Nguồn nước: ${d.water_source || 'Chưa xác định'}\n`;
  if (d.ward_name) response += `   📍 Địa điểm: ${d.ward_name}, ${d.district_name || ''}\n`;
  response += `\n`;
});
return { json: { answer: response } };

let response = "🤖 **Trợ giúp - AgriSupply Chatbot**

";
response += "Tôi có thể giúp bạn với các câu hỏi sau:

";
response += "📊 **Giá thị trường:** "giá hôm nay", "giá rau"
";
response += "✅ **Công việc:** "hôm nay làm gì", "công việc cần làm"
";
response += "🌾 **Khuyến nghị:** "nên trồng gì", "gợi ý cây trồng"
";
response += "🌱 **Vụ mùa:** "tiến độ vụ mùa", "khi nào thu hoạch"
";
response += "⚠️ **Cảnh báo:** "cảnh báo thời tiết", "sâu bệnh"
";
response += "🏡 **Trang trại:** "thông tin trang trại", "diện tích đất"

";
response += "💡 Hãy hỏi tôi bất cứ điều gì liên quan đến nông nghiệp!";
return { json: { answer: response } };

const data = $input.all();
if (!data || data.length === 0 || !data[0].json.question) {
  return { json: { answer: "❓ Xin lỗi, tôi không hiểu câu hỏi của bạn.\n\nGõ \"trợ giúp\" để xem danh sách các câu hỏi tôi có thể trả lời!" } };
}
let response = "❓ **Câu hỏi thường gặp:**\n\n";
data.forEach((item, i) => {
  const d = item.json;
  response += `**${i+1}. ${d.question}**\n`;
  response += `📝 ${d.answer}\n`;
  response += `🏷️ Danh mục: ${d.category}\n\n`;
});
response += "\n💡 Gõ \"trợ giúp\" để xem thêm các câu hỏi khác!";
return { json: { answer: response } };
